import java.util.*;
import java.io.*;

public class Main {
    static long[] swap(long a, long b) {
        // Write your solution here (no third variable)
        return new long[]{a, b};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int t = (int) in.nval;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < t; i++) {
            in.nextToken();
            long a = (long) in.nval;
            in.nextToken();
            long b = (long) in.nval;
            long[] r = swap(a, b);
            sb.append(r[0]).append(" ").append(r[1]).append("\n");
        }
        System.out.print(sb);
    }
}

