def gen(rng):
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join('%d %d' % p for p in ps)

    E = 10**9
    tests = [fmt([(1, 2)]), fmt([(0, 0)]), fmt([(5, 5)]), fmt([(-3, 3)]), fmt([(E, -E)]),
             fmt([(E, E), (-E, -E), (0, E), (-E, 0)]), fmt([(0, 7), (7, 0), (-1, -2)])]
    for _ in range(10):
        k = rng.randint(1, 8)
        tests.append(fmt([(rng.randint(-50, 50), rng.randint(-50, 50)) for _ in range(k)]))
    tests.append(fmt([(rng.randint(-E, E), rng.randint(-E, E)) for _ in range(50000)]))
    tests.append(fmt([(rng.choice([E, -E, 0]), rng.choice([E, -E, 1, -1])) for _ in range(50000)]))
    tests.append(fmt([(rng.randint(1, E), rng.randint(1, E)) for _ in range(50000)]))
    return tests
